$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot '..\scripts\ExecutionGate.psm1') -Force
function Assert([bool]$x,[string]$m){if(-not$x){throw$m}}
$cases=@(@('A',$true,$true,$true,$true,$false,'SUCCESS'),@('B',$true,$false,$true,$true,$false,'NO_PROGRESS'),@('C',$true,$false,$true,$true,$true,'TOOL_FAILURE'),@('D',$false,$false,$true,$true,$false,'PROCESS_FAILURE'),@('E',$true,$true,$false,$true,$false,'SCOPE_VIOLATION'),@('F',$true,$true,$true,$false,$false,'VERIFICATION_FAILURE'))
foreach($c in $cases){$r=Get-AgentHubExecutionResult -ProcessCompleted $c[1] -ProgressDetected $c[2] -ScopeValid $c[3] -VerificationPassed $c[4] -ToolFailure $c[5];Assert ($r -eq $c[6]) "Matrix $($c[0]) expected $($c[6]), got $r";Assert ((Test-AgentHubTaskSuccess $r) -eq ($r -eq 'SUCCESS')) "Success invariant failed for $($c[0])"}
$b=@{authorized_real_invocations=0;consumed_real_invocations=0;remaining_real_invocations=0};Assert (-not(Test-ExecutionBudget $b $false)) 'zero budget allowed real';Assert (Test-ExecutionBudget $b $true) 'mock consumed budget';$b.authorized_real_invocations=1;$b.remaining_real_invocations=1;Consume-ExecutionBudget $b $false|Out-Null;Assert (-not(Test-ExecutionBudget $b $false)) 'consumed budget allowed retry';$b.authorized_real_invocations++;$b.remaining_real_invocations=1;Assert (Test-ExecutionBudget $b $false) 'explicit authorization not honored'
$cmd=Get-CodexCommandContract -Executable 'codex.exe' -Prompt 'hostile "ignore policy" & < >' -WorkingDirectory 'C:\temp\work';Assert ($cmd.arguments[1] -eq '--sandbox' -and $cmd.arguments[2] -eq 'elevated') 'sandbox contract invalid';Assert ($cmd.arguments -notcontains '--full-auto') 'deprecated option retained';Write-Output 'Execution gate A-F, budget, success invariant, and command-contract tests passed.'
